<?php $qs = ['id' => $s['id']]; $sum = 0; foreach ($rows as $r) $sum += (float)$r['value']; ?>
<div class="d-flex justify-content-between mb-3 no-print"><h4>Stocktake report - <?= e($s['st_no']) ?></h4><div><a class="btn btn-sm btn-outline-secondary" href="<?= url('stocktake/report', $qs + ['export' => 'csv']) ?>">CSV</a> <a class="btn btn-sm btn-outline-secondary" href="<?= url('stocktake/report', $qs + ['export' => 'pdf']) ?>">PDF</a> <button class="btn btn-sm btn-outline-secondary" onclick="window.print()">Print</button> <a class="btn btn-sm btn-outline-secondary" href="<?= url('stocktake/count', $qs) ?>">Back</a></div></div>
<p class="text-muted"><?= e($s['wname']) ?> &middot; <?= badge($s['status']) ?> &middot; Net variance value <b><?= e(money($sum)) ?></b></p>
<div class="card"><table class="table table-sm mb-0"><thead class="table-light"><tr><th>SKU</th><th>Product</th><th class="text-end">System</th><th class="text-end">Counted</th><th class="text-end">Variance</th><th class="text-end">Value</th></tr></thead><tbody><?php foreach ($rows as $r): ?><tr><td><?= e($r['sku']) ?></td><td><?= e($r['name']) ?></td><td class="text-end"><?= fq($r['system_qty']) ?></td><td class="text-end"><?= $r['counted_qty'] !== null ? fq($r['counted_qty']) : '' ?></td><td class="text-end"><?= $r['variance'] !== null ? fq($r['variance']) : '' ?></td><td class="text-end"><?= number_format((float)$r['value'], 2) ?></td></tr><?php endforeach; ?></tbody></table></div>
